import{_ as t,o as a,c as r,a5 as o}from"./chunks/framework.bIR-4glx.js";const m=JSON.parse('{"title":"How to Read This Book","description":"A route for a first-time reader of Still Here — start with the story or the method, enter by the problem in front of you, return after an interruption, and leave one page of promises.","frontmatter":{"title":"How to Read This Book","description":"A route for a first-time reader of Still Here — start with the story or the method, enter by the problem in front of you, return after an interruption, and leave one page of promises.","updated":"2026-11-23T00:00:00.000Z"},"headers":[],"relativePath":"en/threads/part-0/reader-guide.md","filePath":"en/threads/part-0/reader-guide.md","lastUpdated":1795392000000}'),n={name:"en/threads/part-0/reader-guide.md"};function i(h,e,d,s,l,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="how-to-read-this-book" tabindex="-1">How to Read This Book <a class="header-anchor" href="#how-to-read-this-book" aria-label="Permalink to &quot;How to Read This Book&quot;">​</a></h1><p>This is not a textbook to memorise from the first page to the last, and it is not a checklist waiting to be ticked. It is closer to a workshop you can return to: bring a real problem in, take a smaller action out, and carry the result back into life.</p><p>If this is your first time here, do not start with “how much should I finish”. Start with: <strong>what do I most need to see clearly, complete, or stop right now?</strong> That question will choose your entrance.</p><h2 id="two-ways-to-read-used-in-turn" tabindex="-1">Two Ways to Read, Used in Turn <a class="header-anchor" href="#two-ways-to-read-used-in-turn" aria-label="Permalink to &quot;Two Ways to Read, Used in Turn&quot;">​</a></h2><h3 id="one-complete-reading-arc" tabindex="-1">One complete reading arc <a class="header-anchor" href="#one-complete-reading-arc" aria-label="Permalink to &quot;One complete reading arc&quot;">​</a></h3><p>Read from beginning to end and pass through four changes:</p><table tabindex="0"><thead><tr><th>Stage</th><th>Reading range</th><th>What you leave with</th></tr></thead><tbody><tr><td>Catch yourself</td><td><a href="./prologue">Prologue</a> · <a href="./../part-2/my-story">My Story</a> · <a href="./../part-2/recovery">Recovery</a></td><td>One reviewable page about the real situation: facts, costs, boundaries, and the next step</td></tr><tr><td>Learn again</td><td><a href="./../part-1/open-input">Part II: Learning Again, Opening Input</a> and its chapters</td><td>An English baseline, one evidence card, and a training cycle you can start</td></tr><tr><td>Amplify and deliver</td><td><a href="./../part-3/amplify-ability">Part III: Amplify Ability</a> · <a href="./../part-4/practice-and-recovery">Part IV: Practice and Recovery</a></td><td>One real delivery, a source record, and an artifact that can be retested</td></tr><tr><td>Entrust to time</td><td><a href="./../part-5/long-term-action">Part V: Long-Term Action</a> · <a href="./../part-6/1-understanding-yourself">Part VI: Be Your Own Lifelong Friend</a> · <a href="./../part-6/afterword">Afterword</a></td><td>A 90-day plan, a cycle review, and a steadier relationship with yourself</td></tr></tbody></table><h3 id="read-it-like-a-workshop" tabindex="-1">Read it like a workshop <a class="header-anchor" href="#read-it-like-a-workshop" aria-label="Permalink to &quot;Read it like a workshop&quot;">​</a></h3><p>Jump straight to the block in front of you from the <a href="./../../reference/reading-map">Reading Map</a>, the contents, or the <a href="./../../reference/glossary">Glossary</a>. Stop after a section, write one judgment, do one exercise, or keep a first-version sample. Later, use the <a href="./../../templates/evidence-chain">Evidence Chain</a> and the <a href="./../../templates/weekly-review">Weekly Review</a> to check whether it transferred to a new task. You do not need to remember the whole book. You only need the next action to be clearer.</p><p>The two ways do not conflict. Reading straight through shows why the method is arranged this way; reading by need lets the method work today.</p><h2 id="four-traces-to-leave-in-every-chapter" tabindex="-1">Four Traces to Leave in Every Chapter <a class="header-anchor" href="#four-traces-to-leave-in-every-chapter" aria-label="Permalink to &quot;Four Traces to Leave in Every Chapter&quot;">​</a></h2><p>Do not only mark a chapter “read”. Leave at least two of these four traces:</p><table tabindex="0"><thead><tr><th>Trace</th><th>The question it answers</th><th>An example</th></tr></thead><tbody><tr><td>A judgment</td><td>What am I more certain of than before?</td><td>“This week I track one main problem.”</td></tr><tr><td>A sample</td><td>What output proves I did it?</td><td>A recording, an email, an error list</td></tr><tr><td>A boundary</td><td>What must not be handed to a tool or to imagination?</td><td>Do not upload client data; do not turn one experience into a rule</td></tr><tr><td>A return point</td><td>When and under what conditions will I retest?</td><td>Redo the same task with a new topic in seven days</td></tr></tbody></table><p>If a chapter leaves you with only “this makes sense”, stop collecting. Rewrite it into an action that someone else can see and you can review.</p><h2 id="when-the-plan-breaks-come-back-here" tabindex="-1">When the Plan Breaks, Come Back Here <a class="header-anchor" href="#when-the-plan-breaks-come-back-here" aria-label="Permalink to &quot;When the Plan Breaks, Come Back Here&quot;">​</a></h2><p>Interruption is not an exception to this method; it is a reality the method has to survive. Open <a href="./../../templates/learning-state">Learning State</a> first and mark what is complete, what is unconfirmed, what it cost, and the next step. If your capacity has changed, return to <a href="./../part-4/daily-system">the minimum viable day</a> or the <a href="./../../templates/rhythm-ledger">Rhythm Ledger</a>. Do not make the plan heavier with shame.</p><p>Add tasks back only when a repeatable rhythm has returned. A reliable system is not one that never breaks. It is one that still knows the way home after it breaks.</p><h2 id="one-page-of-promises-to-the-reader" tabindex="-1">One Page of Promises to the Reader <a class="header-anchor" href="#one-page-of-promises-to-the-reader" aria-label="Permalink to &quot;One Page of Promises to the Reader&quot;">​</a></h2><p>Before you turn the page, write four sentences:</p><ol><li>The real problem I am handling now is:</li><li>The baseline evidence I already have is:</li><li>After this reading, I will complete this smallest action, at this time:</li><li>These information, privacy, health, or relationship boundaries are mine to hold:</li></ol><p>Those four sentences are enough to begin. Reading is not leaving life behind. Reading lets life regain a direction that can be seen.</p><p>For choosing an entrance by a specific problem, preparing for an overseas interview, helping a lower-secondary learner, or checking whether you have really changed, see the full tables in the <a href="./../../reference/reading-map">Reading Map</a>.</p>',22)])])}const u=t(n,[["render",i]]);export{m as __pageData,u as default};
